CREATE OR REPLACE TABLE `cmoore_customer_demos`.`authorization`.`appeal_decision` (
    `appeal_decision_id` STRING COMMENT 'System generated unique identifier for each appeal decision record.',
    `appeal_id` STRING COMMENT 'Unique identifier assigned to the appeal request.',
