    `plan_version_id` STRING COMMENT 'Foreign key linking to product.plan_version. Business justification: Links verification to the specific plan version and benefit design',
    `program_eligibility_id` STRING COMMENT 'Foreign key linking to government.program_eligibility. Business justification: Links verification to government program eligibility (Medicare, Medicaid)',
    `consent_form_id` STRING COMMENT 'Foreign key linking to compliance.consent_form. Business justification: Links verification to member consent for information disclosure',
    `privacy_notice_id` STRING COMMENT 'Foreign key linking to compliance.privacy_notice. Business justification: Links verification to privacy notice acknowledgment',
    `case_id` STRING COMMENT 'Foreign key linking to shared.case. Business justification: Links verification to related case management record',
    `audit_log_id` STRING COMMENT 'Foreign key linking to shared.audit_log. Business justification: Links verification to audit trail for compliance and tracking',
    `assigned_provider_id` STRING COMMENT 'Foreign key linking to provider.provider. Business justification: Links verification to the assigned provider (e.g., PCP)',
    `criteria_id` STRING COMMENT 'Foreign key linking to product.eligibility_criteria. Business justification: Links verification to the eligibility criteria rules applied',
    `status_id` STRING COMMENT 'Foreign key linking to billing.billing_status. Business justification: Links verification to billing status for financial processing',
    `rule_id` STRING COMMENT 'Foreign key linking to shared.eligibility_rule. Business justification: Links verification to the specific eligibility rule evaluated',
    `eligibility_rule_set_id` STRING COMMENT 'Foreign key linking to eligibility.eligibility_rule_set. Business justification: Verification processes are driven by an eligibility_rule_set; adding the FK makes the rule set explicit for each verification.',
    `response_id` STRING COMMENT 'Unique identifier for the eligibility verification response',
    `member_first_name` STRING COMMENT 'The first name of the member whose eligibility is being verified',
    `member_last_name` STRING COMMENT 'The last name of the member whose eligibility is being verified',
    `member_date_of_birth` DATE COMMENT 'The date of birth of the member whose eligibility is being verified, used for identity verification',
    `member_gender` STRING COMMENT 'The gender of the member whose eligibility is being verified (M=Male, F=Female, U=Unknown, O=Other)',
    `member_relationship_code` STRING COMMENT 'The code indicating the members relationship to the primary subscriber (e.g., self, spouse, child, dependent)',
    `subscriber_first_name` STRING COMMENT 'The first name of the primary subscriber on the health plan',
    `subscriber_last_name` STRING COMMENT 'The last name of the primary subscriber on the health plan',
    `subscriber_date_of_birth` DATE COMMENT 'The date of birth of the primary subscriber on the health plan',
    `group_number` STRING COMMENT 'The employer or group identifier associated with the members health plan',
    `policy_number` STRING COMMENT 'The insurance policy number under which the member is covered',
    `provider_npi` STRING COMMENT 'National Provider Identifier of the provider requesting eligibility verification',
    `provider_tin` STRING COMMENT 'Tax Identification Number of the provider organization requesting eligibility verification',
    `provider_name` STRING COMMENT 'Name of the healthcare provider or organization requesting eligibility verification',
    `provider_type` STRING COMMENT 'Type of provider requesting eligibility verification (e.g., physician, hospital, clinic)',
    `service_date` DATE COMMENT 'The date of service for which eligibility is being verified',
    `service_type_code` STRING COMMENT 'The code representing the type of service for which eligibility is being verified (e.g., 30=Plan Coverage, 98=Professional)',
    `service_type_description` STRING COMMENT 'The description of the type of service for which eligibility is being verified',
    `check_date` DATE COMMENT 'The date on which the eligibility verification was performed',
    `check_timestamp` TIMESTAMP COMMENT 'The precise date and time when the eligibility verification was performed',
    `request_timestamp` TIMESTAMP COMMENT 'Date and time when the eligibility verification request was submitted',
    `response_timestamp` TIMESTAMP COMMENT 'Date and time when the eligibility verification response was received',
    `response_time_milliseconds` STRING COMMENT 'The time taken to receive the eligibility response from the payer system, measured in milliseconds',
    `eligibility_status` STRING COMMENT 'Current eligibility status of the member for the requested service (e.g., Active, Inactive, Terminated, Pending)',
    `coverage_start_date` DATE COMMENT 'The date when the members coverage begins or began',
    `coverage_end_date` DATE COMMENT 'The date when the members coverage ends or is scheduled to end',
