    `provider_id` STRING COMMENT 'Foreign key linking to provider.provider. Business justification: Portal users are specific to a provider; replacing provider_npi with provider_id normalizes the relationship and removes duplicate NPI storage.',
    `username` STRING COMMENT 'Login name chosen by the user for portal access.',
    `first_name` STRING COMMENT 'Given name of the portal user.',
    `last_name` STRING COMMENT 'Family name of the portal user.',
    `email_address` STRING COMMENT 'Primary email address for portal communications.',
    `phone_number` STRING COMMENT 'Primary contact phone number for the portal user.',
    `date_of_birth` DATE COMMENT 'Birth date of the portal user, used for age verification.',
    `address_line1` STRING COMMENT 'First line of the users mailing address.',
    `address_line2` STRING COMMENT 'Second line of the users mailing address (optional).',
    `city` STRING COMMENT 'City component of the users mailing address.',
    `state_province` STRING COMMENT 'State or province component of the users mailing address.',
    `postal_code` STRING COMMENT 'ZIP or postal code of the users mailing address.',
    `country_code` STRING COMMENT 'Three-letter ISO country code of the users residence.',
    `role` STRING COMMENT 'Defines the access level and permissions of the portal user within the provider portal.',
    `status` STRING COMMENT 'Current operational status of the portal user account.',
    `created_timestamp` TIMESTAMP COMMENT 'Date and time when the portal user record was created.',
    `modified_timestamp` TIMESTAMP COMMENT 'Date and time of the most recent update to the portal user record.',
    `last_login_timestamp` TIMESTAMP COMMENT 'Date and time of the users most recent successful login to the portal.',
    `password_last_changed` DATE COMMENT 'Date when the user last changed their password.',
    `password_expiration_date` DATE COMMENT 'Date when the current password will expire and must be changed.',
    `failed_login_attempts` STRING COMMENT 'Number of consecutive failed login attempts since last successful login.',
    `account_locked` BOOLEAN COMMENT 'Indicates whether the portal user account is locked due to security policies.',
    `multi_factor_enabled` BOOLEAN COMMENT 'Indicates if the user has enabled multi-factor authentication for portal access.',
    `mfa_method` STRING COMMENT 'Method used for multi-factor authentication.',
    `consent_given` BOOLEAN COMMENT 'Indicates whether the user has provided consent for data sharing as required by HIPAA.',
    `consent_given_timestamp` TIMESTAMP COMMENT 'Date and time when the user gave consent for data sharing.',
    `language_preference` STRING COMMENT 'Preferred language for portal communications.',
    `time_zone` STRING COMMENT 'IANA time zone identifier representing the users local time zone.',
    `network_participation_status` STRING COMMENT 'Indicates the providers participation status in the health network for this portal user.',
    `contract_affiliation` STRING COMMENT 'Identifier of the contract or agreement linking the user to the provider network.',
    CONSTRAINT pk_portal_user PRIMARY KEY(`portal_user_id`)
) COMMENT 'Master reference table for portal_user. Referenced by provider_portal_user_id.';

CREATE OR REPLACE TABLE `cmoore_customer_demos`.`eligibility`.`eligibility_rule_set` (
    `eligibility_rule_set_id` STRING COMMENT 'Primary key for eligibility_rule_set',
    `name` STRING COMMENT 'Human‑readable name of the rule set used for identification.',
    `description` STRING COMMENT 'Detailed description of the purpose and scope of the rule set.',
    `rule_type` STRING COMMENT 'Category of the rule set indicating its primary function.',
    `plan_type` STRING COMMENT 'Type of health insurance plan to which the rule set applies.',
    `benefit_category` STRING COMMENT 'Broad category of benefits governed by the rule set.',
    `effective_date` DATE COMMENT 'Date on which the rule set becomes active.',
    `expiration_date` DATE COMMENT 'Date on which the rule set is retired or no longer applicable.',
    `status` STRING COMMENT 'Current lifecycle status of the rule set.',
    `priority` STRING COMMENT 'Numeric priority used to resolve conflicts when multiple rule sets apply; lower number indicates higher priority.',
    `cob_flag` BOOLEAN COMMENT 'Indicates whether the rule set includes coordination of benefits logic.',
    `hipaa_continuation_flag` BOOLEAN COMMENT 'True if the rule set supports HIPAA continuation coverage after termination.',
    `cobra_flag` BOOLEAN COMMENT 'True if the rule set includes COBRA continuation provisions.',
    `termination_reason_code` STRING COMMENT 'Code representing the business reason for termination of coverage.',
    `termination_date` DATE COMMENT 'Date on which the rule set’s coverage ends, if applicable.',
    `last_review_date` DATE COMMENT 'Date when the rule set was last reviewed for compliance or updates.',
    `review_frequency_days` STRING COMMENT 'Number of days between mandatory reviews of the rule set.',
    `version_number` STRING COMMENT 'Semantic version identifier for the rule set.',
    `is_default` BOOLEAN COMMENT 'Indicates whether this rule set is the default for its plan type and benefit category.',
    `source_system` STRING COMMENT 'Name of the operational system where the rule set originates (e.g., Eligibility Engine, Claims System).',
    `created_timestamp` TIMESTAMP COMMENT 'Date‑time when the rule set record was created in the data lake.',
    `modified_timestamp` TIMESTAMP COMMENT 'Date‑time of the most recent update to the rule set record.',
    CONSTRAINT pk_eligibility_rule_set PRIMARY KEY(`eligibility_rule_set_id`)
) COMMENT 'Master reference table for eligibility_rule_set. Referenced by eligibility_rule_set_id.';

CREATE OR REPLACE TABLE `cmoore_customer_demos`.`eligibility`.`verification_response` (
    `verification_response_id` STRING COMMENT 'Primary key for verification_response',
    `benefit_package_id` STRING COMMENT 'Identifier of the benefit plan under which the member is covered.',
    `payer_id` STRING COMMENT 'Identifier of the insurance payer that issued the response.',
    `verification_id` STRING COMMENT 'Foreign key linking to eligibility.verification. Business justification: Verification response records pertain to a specific verification; linking directly removes duplicated identifiers and ensures referential integrity.',
    `eligibility_status` STRING COMMENT 'Result of the eligibility check indicating whether the member is covered for the requested service.',
    `coverage_type` STRING COMMENT 'Category of benefit coverage applicable to the request.',
    `benefit_plan_name` STRING COMMENT 'Descriptive name of the benefit plan.',
    `effective_date` DATE COMMENT 'Date on which the members coverage becomes effective for the requested service.',
    `termination_date` DATE COMMENT 'Date on which the members coverage ends or is scheduled to end.',
    `service_date` DATE COMMENT 'Date of the healthcare service for which eligibility is being verified.',
    `procedure_code` STRING COMMENT 'Standardized code (CPT or HCPCS) representing the medical procedure or service.',
    `diagnosis_code` STRING COMMENT 'ICD‑10 diagnosis code associated with the service request.',
    `quantity` STRING COMMENT 'Number of units of the service or procedure requested.',
    `allowed_amount` DECIMAL(18,2) COMMENT 'Maximum amount the payer will reimburse for the service.',
    `patient_responsibility_amount` DECIMAL(18,2) COMMENT 'Amount the patient is responsible for paying (copay, coinsurance, deductible).',
    `co_pay_amount` DECIMAL(18,2) COMMENT 'Fixed amount the patient must pay at the time of service.',
    `co_insurance_percent` DECIMAL(18,2) COMMENT 'Percentage of the allowed amount the patient must pay after any deductible.',
    `deductible_amount` DECIMAL(18,2) COMMENT 'Portion of the allowed amount that applies to the members annual deductible.',
    `out_of_pocket_max` DECIMAL(18,2) COMMENT 'Maximum amount the member will pay out of pocket for the benefit period.',
    `network_indicator` STRING COMMENT 'Indicates whether the service is performed in‑network, out‑of‑network, or unknown.',
    `authorization_required` BOOLEAN COMMENT 'Flag indicating whether prior authorization is required for the service.',
    `authorization_number` STRING COMMENT 'Identifier of the prior authorization, if one exists.',
    `response_timestamp` TIMESTAMP COMMENT 'Date‑time when the eligibility response was generated by the payer.',
    `response_code` STRING COMMENT 'Standard code indicating the outcome of the eligibility check (e.g., A1 – approved).',
    `response_message` STRING COMMENT 'Human‑readable message accompanying the response code.',
    `payer_name` STRING COMMENT 'Descriptive name of the insurance payer.',
    `transaction_type` STRING COMMENT 'Type of transaction that generated the response.',
    `source_system` STRING COMMENT 'System or channel through which the eligibility request originated.',
    `error_flag` BOOLEAN COMMENT 'Indicates whether the response contains an error condition.',
    `error_message` STRING COMMENT 'Detailed error description when error_flag is true.',
    `notes` STRING COMMENT 'Free‑form field for additional comments or special handling instructions.',
    CONSTRAINT pk_verification_response PRIMARY KEY(`verification_response_id`)
) COMMENT 'Master reference table for verification_response. Referenced by response_id.';

CREATE OR REPLACE TABLE `cmoore_customer_demos`.`member`.`plan_sponsor` (
    `plan_sponsor_id` STRING COMMENT 'Primary key for plan_sponsor',
    `name` STRING COMMENT 'Legal name of the organization sponsoring the health plan.',
