    `created_timestamp` TIMESTAMP COMMENT 'Timestamp when the sponsor record was first created in the data lake.',
    `updated_timestamp` TIMESTAMP COMMENT 'Timestamp of the most recent update to the sponsor record.',
    CONSTRAINT pk_plan_sponsor PRIMARY KEY(`plan_sponsor_id`)
