CREATE OR REPLACE TABLE `cmoore_customer_demos`.`risk`.`submission_file` (
    `submission_file_id` STRING COMMENT 'Primary key for submission_file',
    `file_name` STRING COMMENT 'Name of the file submitted for risk adjustment.',
    `file_type` STRING COMMENT 'Type of risk adjustment submission file (e.g., RAF, EDPS, RAPS).',
    `submission_cycle` STRING COMMENT 'Frequency cycle for which the file is submitted.',
    `cms_year` STRING COMMENT 'Calendar year for the CMS risk adjustment filing.',
    `submission_date` DATE COMMENT 'Date the file was submitted to CMS.',
    `received_timestamp` TIMESTAMP COMMENT 'Timestamp when the file was received in the system.',
    `status` STRING COMMENT 'Current processing status of the submission file.',
    `record_count` STRING COMMENT 'Number of individual claim or member records contained in the file.',
    `file_size_bytes` STRING COMMENT 'Size of the submission file in bytes.',
    `risk_adjustment_model_version` STRING COMMENT 'Version of the CMS risk adjustment model used for this submission.',
    `hcc_coding_method` STRING COMMENT 'Coding standard used for HCC assignment in the file.',
    `raf_score` DECIMAL(18,2) COMMENT 'Aggregated RAF score calculated for the submission.',
    `rap_score` DECIMAL(18,2) COMMENT 'Aggregated RAP score for the submission.',
