    `effective_date` DATE COMMENT 'Date when the data in the file becomes effective for risk adjustment.',
    `expiration_date` DATE COMMENT 'Date when the data in the file expires or is superseded.',
    CONSTRAINT pk_submission_file PRIMARY KEY(`submission_file_id`)
) COMMENT 'Master reference table for submission_file. Referenced by submission_file_id.';

